Functions created in loops with `var` and `let`: what does this print?

```javascript
const withVar = [];
for (var i = 0; i < 3; i++) {
  withVar.push(() => i);
}

const withLet = [];
for (let j = 0; j < 3; j++) {
  withLet.push(() => j);
}

console.log(withVar.map((f) => f()), withLet.map((f) => f()));
```

`this` in detached methods and callbacks: what does this print?

```javascript
"use strict";
const user = {
  name: "Rafi",
  regular() { return this?.name; },
  arrow: () => this?.name,
  nested() { return [1].map(function () { return this?.name; })[0]; },
  nestedArrow() { return [1].map(() => this.name)[0]; },
};

const { regular } = user;
console.log(user.regular(), regular());
console.log(user.arrow(), user.nested(), user.nestedArrow());
```

Timers and promise chains: what does this print?

```javascript
console.log(1);
setTimeout(() => console.log(2), 0);
Promise.resolve()
  .then(() => console.log(3))
  .then(() => console.log(4));
setTimeout(() => console.log(5), 0);
console.log(6);
```

`async`/`await` ordering: what does this print?

```javascript
async function a() {
  console.log("a1");
  await b();
  console.log("a2");
}
async function b() {
  console.log("b");
}

console.log("start");
setTimeout(() => console.log("timeout"), 0);
a();
Promise.resolve().then(() => console.log("promise"));
console.log("end");
```

`["1", "2", "3"].map(parseInt)`: what does this print?

```javascript
console.log(["1", "2", "3"].map(parseInt));
console.log(["10", "10", "10"].map(parseInt));
console.log(["1", "2", "3"].map(Number));
console.log(["1", "2", "3"].map((s) => parseInt(s, 10)));
```

Objects as object keys: what does this print?

```javascript
const store = {};
const b = { key: "b" };
const c = { key: "c" };

store[b] = 123;
store[c] = 456;
console.log(store[b], Object.keys(store));

const map = new Map([[b, 123], [c, 456]]);
console.log(map.get(b), map.size);
```

